/* Both operands are actual pending completions owned by a native reducer.
   Releasing a losing private event is an owner decision, not public Cancel:
   a detached event is eligible here and a later unserviced request stays set. */
bool JS_PiNativePendingReplace(JSRuntime *rt, JSValueConst retained,
                                JSValueConst incoming)
{
    bool replace = js_pi_pending_priority(rt, incoming) >
                   js_pi_pending_priority(rt, retained);
    JSValueConst selected = replace ? incoming : retained;
    JSValueConst discarded = replace ? retained : incoming;
    if (JS_PiIsExecutionTermination(discarded) &&
        !JS_PiIsExecutionTermination(selected))
        rt->pi_termination_in_flight = false;
    return replace;
}

static void js_native_async_take_pending(JSContext *ctx, JSNativeAsyncPending *owned);

JS_EXTERN uint64_t JS_PiExecutionTerminationGeneration(JSRuntime *rt);
/* Borrowed actual pending reasons only, never retained/returned DATA. Returns
   whether incoming replaces retained under the existing first-fatal rule and
   the cancelled native-completion precedence. If a private event loses, retires
   its in-flight lease without clearing a later unserviced request. Neither
   operand is freed; the caller retires the losing owned value. No allocation,
   guest call, pending-slot mutation or public Error-flag inference is added. */
JS_EXTERN bool JS_PiNativePendingReplace(JSRuntime *rt,
                                         JSValueConst retained_pending,
                                         JSValueConst incoming_pending);
